```go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
)

type StructInfo struct {
	Name        string
	Package     string
	Fields      []FieldInfo
}

type FieldInfo struct {
	Type  string
	Name  string
	Comment string
}

func readStructs(srcFile string) map[string]*StructInfo {
	var structs map[string]*StructInfo = make(map[string]*StructInfo)
	err := filepath.Walk(srcFile, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() && path[len(srcFile):] == ".go" {
			file, err := parser.ParseFile(token.NewFileSet(), path, "", parser.AllErrors)
			if err != nil {
				log.Fatalf("Failed to parse %q: %v", path, err)
			}
			for _, decl := range file.Decls {
				switch d := decl.(type) {
				case *ast.StructType:
					structName := ""
					for i := 0; i < len(d.Fields); i++ {
						field := d.Fields[i]
						if field.Names[0].Kind == token.NAME {
							structName += fmt.Sprintf("%s_", field.Names[0].Name)
						} else if field.Names[1].Kind == token.STRING {
							structName += fmt.Sprintf("_%s", field.Names[1].Value)
						}
					}
					structName = strings.TrimPrefix(structName, "struct_")
					structs[structName] = &StructInfo{
						Name:        structName,
						Package:     srcFile[:srcFile.LastIndex('/')],
						Fields:      extractFields(d),
						Comments:    extractComments(info.Name),
					}
				default:
					continue
				}
			}
		}
		return nil
	})
	if err != nil {
		log.Fatalf("Error parsing package structure: %v", err)
	}
	return structs
}

func extractFields(decl *ast.StructType) []FieldInfo {
	fields := make([]FieldInfo, 0)
	for i := 0; i < len(decl.Fields); i++ {
		field := decl.Fields[i]
		typeName := ""
		comment := ""

		if fieldName, ok := field.Names[0].(*token.Label).String(); ok {
			typeName = fieldName
		} else if fieldType, ok := field.Names[1].(*token.StringLiteral).Value; ok {
			typeName = fieldType
		}

		if commentStr, ok := field.Comment.List[0].Text; ok {
			comment = commentStr
		}

		fields = append(fields, FieldInfo{Type: typeName, Name: fieldName, Comment: comment})
	}
	return fields
}

func extractComments(file string) []string {
	content, err := ioutil.ReadFile(file)
	if err != nil {
		log.Fatalf("Failed to open file %q: %v", file, err)
	}
	lines := content.Split('\n')
	comments := make([]string, 0)
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			comments = append(comments, line)
		}
	}
	return comments
}

